pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // General rule: for ANY actor and ANY newOwner, a call to transferOwnership
    // that is relayed through an intermediary contract must REVERT, because
    // only the immediate caller (msg.sender) may be the owner.
    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.assume(newOwner != address(c));

        // Set the owner to the fuzzed actor (initial owner is address(0), so the
        // very first ownership transfer from address(0) succeeds in P and M alike).
        vm.prank(address(0));
        c.transferOwnership(actor);
        assertEq(c.owner(), actor);

        // Relayed call: the owner (tx.origin = actor) calls through an
        // intermediary contract, so c sees msg.sender = intermediary.
        Middle m = new Middle();
        vm.prank(actor);
        bool ok;
        try m.relay(c, newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference: relayed ownership transfer is ALWAYS rejected.
        assertTrue(!ok, "relayed transferOwnership must revert");
        // (In the tx.origin mutant, tx.origin == owner == actor passes the
        //  modifier, ok becomes true and owner becomes newOwner, breaking the rule.)
    }
}

contract Middle {
    function relay(C c, address newOwner) external {
        c.transferOwnership(newOwner);
    }
}

